import { describe, expect, test } from 'vitest';

import { parseChangelog } from './changelog';

const MARKDOWN = `# Changelog

<!-- Generated by tool/generate_changelog.sh -->

## 2026-10-29

- Add pinned transit journeys (\`abc1234\`)
- Polish the overview (no hash)

## 2026-10-15

- Make leave-time alerts reliable: audio unlock (\`24812e2\`)
`;

describe('parseChangelog', () => {
  test('groups entries by date', () => {
    const parsed = parseChangelog(MARKDOWN);
    expect(parsed.sections).toHaveLength(2);
    expect(parsed.sections[0]!.date).toBe('2026-10-29');
    expect(parsed.sections[0]!.entries).toHaveLength(2);
    expect(parsed.sections[1]!.date).toBe('2026-10-15');
  });

  test('extracts the commit hash and strips it from the text', () => {
    const entry = parseChangelog(MARKDOWN).sections[0]!.entries[0]!;
    expect(entry.hash).toBe('abc1234');
    expect(entry.text).toBe('Add pinned transit journeys');
  });

  test('handles entries without a hash', () => {
    const entry = parseChangelog(MARKDOWN).sections[0]!.entries[1]!;
    expect(entry.hash).toBeNull();
    expect(entry.text).toBe('Polish the overview (no hash)');
  });

  test('returns no sections for an empty document', () => {
    expect(parseChangelog('# Changelog\n').sections).toEqual([]);
  });
});
